<script setup>
import { hasPermission } from '../../utils/permissions'
import { computed, onMounted, ref } from 'vue'
import { confirmAction } from '../../composables/confirmAction'
import { useRouter } from 'vue-router'
import BaseButton from '../../components/ui/BaseButton.vue'
import BaseInput from '../../components/ui/BaseInput.vue'
import { customerProfileService } from '../../services/customerProfileService'
const router=useRouter()
const rows=ref([])
const loading=ref(false)
const errorMessage=ref('')
const successMessage=ref('')
const search=ref('')
const normalize=value=>String(value??'').trim().toLowerCase()
const visibleRows=computed(()=>{const q=search.value.trim().toLowerCase();return rows.value.filter(row=>!q||[row.first_name,row.middle_name,row.last_name,row.phone,row.email,row.city,row.state_province,row.country].some(value=>String(value??'').toLowerCase().includes(q)))})
function recordId(row){return row.id??row.customer_profile_id??row.uuid}
function fullName(row){return [row.first_name,row.middle_name,row.last_name].filter(Boolean).join(' ')||'Unnamed customer'}
function initials(row){return fullName(row).split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'C'}
function initialsTone(row){const tones=['tone-teal','tone-blue','tone-violet','tone-amber'];const seed=fullName(row).split('').reduce((sum,char)=>sum+char.charCodeAt(0),0);return tones[seed%tones.length]}
async function loadRows(){loading.value=true;errorMessage.value='';try{const response=await customerProfileService.list();const payload=response?.data;rows.value=Array.isArray(payload)?payload:Array.isArray(payload?.data)?payload.data:Array.isArray(response)?response:[]}catch(error){errorMessage.value=error?.message||'Unable to load customer profiles.'}finally{loading.value=false}}
async function deleteRow(row){const id=recordId(row);if(!id){errorMessage.value='This customer profile has no record ID and cannot be deleted.';return}const confirmed=await confirmAction({title:'Delete customer profile',message:`Delete customer profile for ${fullName(row)}? This action cannot be undone.`});if(!confirmed)return;errorMessage.value='';successMessage.value='';try{await customerProfileService.remove(id);successMessage.value='Customer profile deleted.';await loadRows()}catch(error){errorMessage.value=error?.message||'Unable to delete customer profile.'}}
onMounted(loadRows)
</script>
<template>
<section class="module-page customers-page">
  <div class="customers-heading"><div><h2>Customers</h2><p>Customer details captured during trades appear here when supported by the backend.</p></div></div>
  <div class="customers-metrics"><article class="customers-metric"><span class="metric-icon metric-icon-total">♙</span><div><p>Total customers</p><strong>{{ rows.length }}</strong></div></article><article class="customers-metric"><span class="metric-icon metric-icon-contact">☎</span><div><p>Customers with contact details</p><strong>{{ rows.filter(row=>row.phone||row.email).length }}</strong></div></article></div>
  <p v-if="errorMessage" class="customers-alert customers-alert-error" role="alert">{{ errorMessage }}</p><p v-if="successMessage" class="customers-alert customers-alert-success" role="status">{{ successMessage }}</p>
  <section class="customers-register-card"><div class="customers-register-head"><div><div class="customers-register-title"><h3>All customers</h3><span class="customers-count">{{ visibleRows.length }}</span></div><p>Search customer records and select an action to view or update a profile.</p></div><label class="customers-search"><span aria-hidden="true">⌕</span><BaseInput v-model="search" placeholder="Search name, phone, email…" aria-label="Search customers" size="sm" /><button v-if="search" type="button" aria-label="Clear search" @click="search=''">×</button></label></div>
  <div class="customers-table-wrap"><table class="module-table customers-table"><thead><tr><th>Customer</th><th>Contact details</th><th>Location</th><th>Actions</th></tr></thead><tbody>
    <tr v-if="loading"><td colspan="4" class="module-empty-state">Loading customers…</td></tr><tr v-else-if="!visibleRows.length"><td colspan="4" class="module-empty-state">No customers found.</td></tr>
    <tr v-for="row in visibleRows" :key="recordId(row)??fullName(row)" class="customers-data-row"><td class="customers-person-cell"><span class="customers-avatar" :class="initialsTone(row)">{{ initials(row) }}</span><span class="customers-person-copy"><strong>{{ fullName(row) }}</strong><small>Customer</small></span></td><td class="customers-contact-cell"><strong>{{ row.phone||'—' }}</strong><span>{{ row.email||'No email provided' }}</span></td><td class="customers-location-cell"><strong>{{ row.city||row.state_province||row.country||'—' }}</strong><span>{{ [row.state_province,row.country].filter(Boolean).join(', ')||'Location not specified' }}</span></td><td class="customers-row-actions"><button class="customers-view-action" :disabled="!recordId(row)" @click="router.push(`/customers/${encodeURIComponent(recordId(row))}`)">View ↗</button><button v-if="hasPermission('customer-profiles:delete')" class="customers-delete-action" :disabled="!recordId(row)" aria-label="Delete customer" @click="deleteRow(row)">⌫</button></td></tr>
  </tbody></table></div><footer class="customers-table-footer"><span>Showing <strong>{{ visibleRows.length }}</strong> of <strong>{{ rows.length }}</strong> customers</span><span>Data reflects the latest loaded records</span></footer></section>
</section>
</template>
