center;gap:8px;width:270px;min-width:175px;height:39px;padding:0 10px;border:1px solid #dce5ed;border-radius:8px;background:#fff;color:#73869a}.customers-search :deep(input){min-width:0;width:100%;height:35px;padding:0;border:0;outline:0;background:transparent;font-size:12px}.customers-search button{border:0;background:transparent;color:#718198;font-size:18px}.customers-table-wrap{width:100%;overflow-x:auto}.customers-table{min-width:760px}.customers-table th{padding:13px 17px!important;background:#f7f9fc!important;color:#5e7187!important;font-size:10px!important;font-weight:800!important;letter-spacing:.075em!important}.customers-table td{padding:16px 17px!important;border-top:1px solid #edf1f5!important;font-size:12px!important;vertical-align:middle}.customers-person-cell{display:flex;align-items:center;gap:11px;min-width:195px}.customers-avatar{display:grid;place-items:center;flex:0 0 39px;width:39px;height:39px;border-radius:12px;font-size:11px;font-weight:800}.tone-teal{background:#e1f6f1;color:#087d6d}.tone-blue{background:#e7f0ff;color:#285fbb}.tone-violet{background:#f0eaff;color:#7652b4}.tone-amber{background:#fff1d9;color:#9c650d}.customers-person-copy{display:grid;gap:4px}.customers-person-copy strong,.customers-contact-cell strong,.customers-location-cell strong{color:#1b3048;font-size:13px;font-weight:750}.customers-person-copy small,.customers-contact-cell span,.customers-location-cell span{display:block;margin-top:4px;color:#8291a1;font-size:10px}.customers-row-actions{display:flex;align-items:center;justify-content:flex-end;gap:5px}.customers-row-actions button{display:inline-flex;align-items:center;justify-content:center;min-width:31px;height:31px;padding:0 8px;border:1px solid #e0e8ef;border-radius:7px;background:#fff;color:#587087;font-size:12px;font-weight:700}.customers-row-actions .customers-view-action{gap:5px;border-color:#cde9e3;background:#effaf7;color:#087e70;font-size:11px}.customers-row-actions button:disabled{cursor:not-allowed;opacity:.45}.customers-table-footer{display:flex;justify-content:space-between;gap:14px;padding:13px 20px;border-top:1px solid #edf1f5;background:#fbfcfe;color:#718198;font-size:11px}.customers-table-footer strong{color:#334b62}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:800px){.customers-register-head{align-items:flex-start;flex-direction:column}.customers-search{width:100%}}@media(max-width:700px){.customers-heading{align-items:flex-start;flex-direction:column}.customers-metrics{grid-template-columns:1fr}.customers-table-footer{flex-direction:column}}
</style>
